pattern.example:
use thiserror::Error;
#[derive(Error, Debug)] pub enum StorageError { #[error("record {id} not found in {table}")] NotFound { table: &'static str, id: String },
#[error("duplicate key: {0}")] Conflict(String),
#[error(transparent)] Database(#[from] sqlx::Error),
#[error(transparent)] Io(#[from] std::io::Error), }

use anyhow::{bail, Context, Result};

fn load_config(path: &str) -> Result<Config> {
    let raw = std::fs::read_to_string(path)
        .with_context(|| format!("reading config from {path}"))?;

    let config: Config = toml::from_str(&raw)
        .context("parsing TOML config")?;

    if config.port == 0 {
        bail!("port must be non-zero");
    }

    Ok(config)
}

fn create_user(db: &Pool, input: &NewUser) -> Result<User, AppError> {
    validate_email(&input.email)?;   // ValidationError -> AppError via From
    let user = db.insert(input)?;    // sqlx::Error -> AppError via From
    Ok(user)
}

use axum::{extract::{Path, State}, http::StatusCode, Json};
use std::sync::Arc;

async fn get_user(
    State(state): State<Arc<AppState>>,
    Path(id): Path<String>,
) -> Result<Json<User>, StatusCode> {
    state
        .user_service
        .get_by_id(&id)
        .await
        .map(Json)
        .map_err(|e| match e {
            ServiceError::NotFound => StatusCode::NOT_FOUND,
            _ => StatusCode::INTERNAL_SERVER_ERROR,
        })
}

