#[derive(Debug)]
pub struct ServerConfig {
    pub host: String,
    pub port: u16,
    pub max_connections: usize,
    pub timeout: Duration,
}

pub struct ServerConfigBuilder {
    host: String,
    port: u16,
    max_connections: Option<usize>,
    timeout: Option<Duration>,
}

impl ServerConfigBuilder {
    pub fn new(host: impl Into<String>, port: u16) -> Self {
        Self { host: host.into(), port, max_connections: None, timeout: None }
    }
    pub fn max_connections(mut self, n: usize) -> Self {
        self.max_connections = Some(n); self
    }
    pub fn timeout(mut self, d: Duration) -> Self {
        self.timeout = Some(d); self
    }
    pub fn build(self) -> ServerConfig {
        ServerConfig {
            host: self.host,
            port: self.port,
            max_connections: self.max_connections.unwrap_or(100),
            timeout: self.timeout.unwrap_or(Duration::from_secs(30)),
        }
    }
}

error-handling.pattern:
// src/error.rs
#[derive(thiserror::Error, Debug)]
pub enum AppError {
    #[error("not found: {0}")]
    NotFound(String),
    #[error(transparent)]
    Database(#[from] sqlx::Error),
    #[error(transparent)]
    Io(#[from] std::io::Error),
}

use anyhow::{Context, Result};

fn run() -> Result<()> {
    let db = connect()
        .context("connecting to database")?;
    // errors carry a full context chain when printed with {:#}
    Ok(())
}

// Define From<ExternalError> for AppError (via #[from] in thiserror),
// then ? converts automatically at each call site.
fn save_user(user: &User) -> Result<(), AppError> {
    validate(user)?;         // ValidationError -> AppError
    db.insert(user)?;        // sqlx::Error -> AppError
    Ok(())
}

