#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parse_valid_email_succeeds() {
        assert!(Email::parse("user@example.com").is_ok());
    }

    #[test]
    fn parse_invalid_email_returns_error() {
        let err = Email::parse("not-an-email").unwrap_err();
        assert!(matches!(err, ValidationError::InvalidEmail(_)));
    }
}

// tests/api_test.rs
#[tokio::test]
async fn health_endpoint_returns_200() {
    let app = build_test_app().await;
    let resp = app.oneshot(Request::builder()
        .uri("/health")
        .body(Body::empty())
        .unwrap())
        .await
        .unwrap();
    assert_eq!(resp.status(), StatusCode::OK);
}

use proptest::prelude::*;

proptest! {
    #[test]
    fn encode_decode_roundtrip(s in "[a-zA-Z0-9]{1,100}") {
        let encoded = encode(&s);
        let decoded = decode(&encoded).expect("valid encoded string");
        prop_assert_eq!(s, decoded);
    }
}

